def seed_ma_counties_and_municipalities(apps, schema_editor):
    State = apps.get_model('core', 'State')
    County = apps.get_model('core', 'County')
    CityTown = apps.get_model('core', 'CityTown')

    state, _ = State.objects.get_or_create(code='MA', defaults={'name': 'Massachusetts'})

    county_map = {}
    for county_name in MA_COUNTIES:
        county, _ = County.objects.get_or_create(state=state, name=county_name)
        county_map[county_name] = county

    for county_name, municipality_name in MA_MUNICIPALITIES:
        county = county_map[county_name]
        CityTown.objects.get_or_create(county=county, name=municipality_name)

